struct framebuffer { int fd; unsigned char *memory; size_t mapped_length; struct fb_var_screeninfo var; struct fb_fix_screeninfo fix; };
struct experiment_state {
    char name[RB_TEXT_MAX]; char user[RB_TEXT_MAX]; char status[16]; char dataset[RB_TEXT_MAX];
    char metric_name[RB_TEXT_MAX]; char metric_value[24];
    char job_name[RB_TEXT_MAX]; char job_method[RB_TEXT_MAX];
    int matrix_completed; int matrix_total; int current_cell;
    int progress; int current_round; int total_round; int elapsed_seconds; int seed;
};
struct local_state {
    char server[RB_TEXT_MAX]; char server_status[16]; char server_freshness[12]; char codex_freshness[12]; char gpu_memory_used[16]; char gpu_memory_total[16];
    char current_time[8]; char updated_label[24];
    char job_name[RB_TEXT_MAX]; char job_method[RB_TEXT_MAX];
    int matrix_completed; int matrix_total; int current_cell;
    int cpu; int ram; int gpu; int updated_age_seconds; int experiment_count; struct experiment_state experiment[2];
    int five_hour; int week; int reset_cards; char five_hour_reset[24]; char week_reset[24]; uint32_t sequence; int valid;
};

static void draw_matrix_experiment(struct framebuffer *fb,const struct experiment_state *e,const char *gpu_memory_used,const char *gpu_memory_total,uint32_t text,uint32_t muted,uint32_t green,uint32_t yellow,uint32_t red,uint32_t border);
static void draw_matrix_footer(struct framebuffer *fb,const struct local_state *state,uint32_t text,uint32_t muted,uint32_t panel);

static uint32_t pack_component(uint8_t value, const struct fb_bitfield *field) { uint32_t max; if (!field->length) return 0; max=(1U<<field->length)-1U; return (((uint32_t)value*max+127U)/255U)<<field->offset; }
static uint32_t pack_rgb(const struct fb_var_screeninfo *var, uint8_t r, uint8_t g, uint8_t b) { return pack_component(r,&var->red)|pack_component(g,&var->green)|pack_component(b,&var->blue); }
static int fb_open(struct framebuffer *fb) { fb->fd=open("/dev/fb0",O_RDWR); if(fb->fd<0)return -1; if(ioctl(fb->fd,FBIOGET_VSCREENINFO,&fb->var)<0||ioctl(fb->fd,FBIOGET_FSCREENINFO,&fb->fix)<0||fb->var.bits_per_pixel!=16){close(fb->fd);return -1;} fb->mapped_length=fb->fix.smem_len; fb->memory=mmap(NULL,fb->mapped_length,PROT_READ|PROT_WRITE,MAP_SHARED,fb->fd,0); if(fb->memory==MAP_FAILED){close(fb->fd);return -1;} return 0; }
static void fb_close(struct framebuffer *fb) { if(fb->memory!=MAP_FAILED)munmap(fb->memory,fb->mapped_length); if(fb->fd>=0)close(fb->fd); }
static void pixel(struct framebuffer *fb,int x,int y,uint32_t color) { uint16_t p; unsigned char *a; if(x<0||y<0||(uint32_t)x>=fb->var.xres||(uint32_t)y>=fb->var.yres)return; a=fb->memory+(size_t)y*fb->fix.line_length+(size_t)x*2U;p=(uint16_t)color;memcpy(a,&p,2); }
static void rect(struct framebuffer *fb,int x,int y,int w,int h,uint32_t c) { int xx,yy; for(yy=y;yy<y+h;yy++)for(xx=x;xx<x+w;xx++)pixel(fb,xx,yy,c); }
static void line_rect(struct framebuffer *fb,int x,int y,int w,int h,uint32_t c) { int i; for(i=x;i<x+w;i++){pixel(fb,i,y,c);pixel(fb,i,y+h-1,c);} for(i=y;i<y+h;i++){pixel(fb,x,i,c);pixel(fb,x+w-1,i,c);} }
static const struct font_glyph *find_glyph(const struct font_face *font,char c){uint8_t i;for(i=0;i<font->count;i++)if(font->glyphs[i].code==(uint8_t)c)return &font->glyphs[i];return NULL;}
static int text_width(const struct font_face *font,const char *s,int spacing){int w=0,n=0;while(*s){const struct font_glyph *g=find_glyph(font,*s++);if(g){w+=g->advance;n++;}}return n>1?w+(n-1)*spacing:w;}
static void draw_text(struct framebuffer *fb,int x,int y,const struct font_face *font,const char *s,int spacing,uint32_t color){while(*s){const struct font_glyph *g=find_glyph(font,*s++);if(g){int r,c,stride=(g->width+7)/8;for(r=0;r<g->height;r++)for(c=0;c<g->width;c++){uint8_t a=g->format==FONT_BITMAP_ALPHA?g->data[r*g->width+c]:(g->data[r*stride+c/8]&(uint8_t)(0x80U>>(c%8))?255:0);if(a)pixel(fb,x+c,y+r,color);}x+=g->advance+spacing;}}}
static void draw_text_scaled3(struct framebuffer *fb,int x,int y,const struct font_face *font,const char *s,uint32_t color){while(*s){const struct font_glyph *g=find_glyph(font,*s++);if(g){int r,c,stride=(g->width+7)/8;for(r=0;r<g->height;r++)for(c=0;c<g->width;c++){uint8_t a=g->format==FONT_BITMAP_ALPHA?g->data[r*g->width+c]:(g->data[r*stride+c/8]&(uint8_t)(0x80U>>(c%8))?255:0);if(a)pixel(fb,x+(c*3)/4,y+(r*3)/4,color);}x+=(g->advance*3+3)/4;}}}
static void copy_text(char *out,const char *in){while((*out++=*in++)!='\0'){} }
static const char *last_parse_reason="none";
static int last_length_ok=0,last_crc_ok=0;
static int text_length(const char *text){int n=0;while(text[n])n++;return n;}
static int same_text(const char *a,const char *b){while(*a&&*a==*b){a++;b++;}return *a=='\0'&&*b=='\0';}
static void append_text(char *out,const char *in,int max){int n=text_length(out),i=0;while(in[i]&&n<max-1)out[n++]=in[i++];out[n]='\0';}
static void number_text(char *out,int value){char r[16];int n=0,i,negative=value<0;if(negative)value=-value;do{r[n++]=(char)('0'+value%10);value/=10;}while(value);if(negative)*out++='-';for(i=0;i<n;i++)out[i]=r[n-i-1];out[n]='\0';}
static int hex_value(char c){if(c>='0'&&c<='9')return c-'0';if(c>='A'&&c<='F')return c-'A'+10;if(c>='a'&&c<='f')return c-'a'+10;return -1;}
static void decode_text(char *out,int max,const char *in){int n=0;while(*in&&n<max-1){if(in[0]=='%'&&hex_value(in[1])>=0&&hex_value(in[2])>=0){out[n++]=(char)(hex_value(in[1])*16+hex_value(in[2]));in+=3;}else out[n++]=*in++;}out[n]='\0';}
static void normalize_display(char *out,const char *in,int max){int n=0;while(in[n]&&n<max-1){char c=in[n];if(c>='a'&&c<='z')c=(char)(c-'a'+'A');out[n++]=c;}out[n]='\0';}
static void draw_fit(struct framebuffer *fb,int x,int y,const struct font_face *font,const char *text,int spacing,uint32_t color,int max_width){char display[RB_TEXT_MAX],clipped[RB_TEXT_MAX],candidate[RB_TEXT_MAX];int n=0,resource_width,resource_x;if(x==RB_STATUS_X&&same_text(text,"DEGRADED"))spacing=0;normalize_display(display,text,sizeof(display));if(!display[0])return;if(x==RB_RESOURCE_X&&max_width==RB_RESOURCE_W&&font==&font_label){resource_width=text_width(font,display,spacing);resource_x=RB_RESOURCE_RIGHT-resource_width;if(resource_width<=max_width&&resource_x>=RB_RESOURCE_X){draw_text(fb,resource_x,y,font,display,spacing,color);return;}}if(text_width(font,display,spacing)<=max_width){draw_text(fb,x,y,font,display,spacing,color);return;}while(display[n]&&n<RB_TEXT_MAX-1){clipped[n]=display[n];clipped[n+1]='\0';if(text_width(font,clipped,spacing)>max_width)break;n++;}if(!n)return;if(display[n]&&n>=5){int prefix=n;while(prefix>=5){copy_text(candidate,clipped);candidate[prefix]='.';candidate[prefix+1]='.';candidate[prefix+2]='.';candidate[prefix+3]='\0';if(text_width(font,candidate,spacing)<=max_width){copy_text(clipped,candidate);break;}prefix--;}if(prefix<5)clipped[n]='\0';}draw_text(fb,x,y,font,clipped,spacing,color);}
static int parse_int(const char *s,int n,int *out){int i=0,neg=0,v=0;if(!n)return 0;if(s[0]=='-'){neg=1;i++;}if(i==n)return 0;for(;i<n;i++){if(s[i]<'0'||s[i]>'9')return 0;v=v*10+s[i]-'0';if(v>1000000000)return 0;}*out=neg?-v:v;return 1;}
static int field(const char *payload,int length,const char *key,char *value,int max){int p=0,klen=text_length(key);while(p<length){int start=p,end,eq,i;while(p<length&&payload[p]!='|')p++;end=p;eq=start;while(eq<end&&payload[eq]!='=')eq++;if(eq-start==klen){for(i=0;i<klen;i++)if(payload[start+i]!=key[i])break;if(i==klen){int n=end-eq-1;if(n<=0||n>=max)return 0;memcpy(value,payload+eq+1,n);value[n]='\0';return 1;}}if(p<length)p++;}return 0;}
static int integer_field(const char *payload,int length,const char *key,int *value){char text[24];return field(payload,length,key,text,sizeof(text))&&!same_text(text,"?")&&parse_int(text,text_length(text),value);}
static int percent_field(const char *payload,int length,const char *key,int *value){char text[24];int i,n,after=0,whole=0,frac=0,frac_digits=0,scale=1,milli;if(!field(payload,length,key,text,sizeof(text))||same_text(text,"?"))return 0;n=text_length(text);if(!n)return 0;for(i=0;i<n;i++){char c=text[i];if(c>='0'&&c<='9'){if(after){if(frac_digits>=3)return 0;frac=frac*10+c-'0';frac_digits++;}else{whole=whole*10+c-'0';if(whole>1000)return 0;}}else if(c=='.'&&!after){after=1;}else return 0;}if(after&&!frac_digits)return 0;for(i=0;i<frac_digits;i++)scale*=10;milli=whole*1000+(frac_digits?frac*(1000/scale):0);*value=(milli+500)/1000;return *value>=0&&*value<=100;}
static int text_field(const char *payload,int length,const char *key,char *out,int max){char value[RB_TEXT_MAX];if(!field(payload,length,key,value,sizeof(value))||same_text(value,"?"))return 0;decode_text(out,max,value);return 1;}
static void experiment_key(char *out,int index,const char *suffix){out[0]='E';out[1]=(char)('0'+index);copy_text(out+2,suffix);}
static uint16_t crc16(const unsigned char *data,int length){uint16_t crc=0xFFFF;int i;while(length--){crc^=(uint16_t)*data++<<8;for(i=0;i<8;i++)crc=(uint16_t)((crc&0x8000)?(crc<<1)^0x1021:crc<<1);}return crc;}
static const char *find_text(const char *haystack,const char *needle){int n=text_length(needle),i;if(!n)return haystack;for(;*haystack;haystack++){for(i=0;i<n&&haystack[i]==needle[i];i++){}if(i==n)return haystack;}return NULL;}

static int parse_fail(const char *reason){last_parse_reason=reason;return 0;}
static void timestamp_clock(char *out,const char *timestamp);
static void format_updated(char *out,int seconds);

static int parse_rb1(const char *frame,int length,struct local_state *state){
    int i,pipe=0,payload_length=-1,crc_position=-1,provided,count,sequence;char payload[RB_FRAME_MAX+1],value[RB_TEXT_MAX];struct local_state parsed=*state;
    last_parse_reason="header";last_length_ok=0;last_crc_ok=0;
    if(length<12||frame[0]!='R'||frame[1]!='B'||frame[2]!='1'||frame[3]!='|'||frame[length-1]!='\n')return parse_fail("header");
    for(i=0;i<length;i++){if(frame[i]=='|')pipe++;}if(pipe<4)return parse_fail("framing");
    {const char *start=frame+6;int digits=0;while(start[digits]>='0'&&start[digits]<='9')digits++;if(digits<1||digits>3||!parse_int(start,digits,&payload_length)||payload_length<1||payload_length>RB_FRAME_MAX)return parse_fail("length");last_length_ok=1;}
    for(i=length-6;i>=4;i--){if(frame[i]=='|'&&frame[i+1]=='C'&&frame[i+2]=='R'&&frame[i+3]=='C'&&frame[i+4]=='='){crc_position=i;break;}}if(crc_position<0)return parse_fail("crc-marker");
    {const char *start=find_text(frame,"|V=");if(!start)return parse_fail("payload");start++;if(frame+crc_position-start!=payload_length)return parse_fail("length");memcpy(payload,start,(size_t)payload_length);payload[payload_length]='\0';}
    provided=0;for(i=crc_position+5;i<length-1;i++){int digit=hex_value(frame[i]);if(digit<0)return parse_fail("crc-format");provided=(provided<<4)|digit;}if(i-(crc_position+5)!=4)return parse_fail("crc-format");if((provided&0xFFFF)!=crc16((unsigned char *)payload,payload_length))return parse_fail("crc");last_crc_ok=1;
    if(!text_field(payload,payload_length,"V",value,sizeof(value))||!same_text(value,"1"))return parse_fail("version");
    parsed.valid=1;sequence=0;if(integer_field(payload,payload_length,"SEQ",&sequence))parsed.sequence=(uint32_t)sequence;
    if(text_field(payload,payload_length,"SD",parsed.server,sizeof(parsed.server))==0)copy_text(parsed.server,"SERVER-01");
    if(text_field(payload,payload_length,"SS",parsed.server_status,sizeof(parsed.server_status))==0)copy_text(parsed.server_status,"offline");
    if(text_field(payload,payload_length,"SF",parsed.server_freshness,sizeof(parsed.server_freshness))==0)copy_text(parsed.server_freshness,"fresh");
    if(text_field(payload,payload_length,"CF",parsed.codex_freshness,sizeof(parsed.codex_freshness))==0)copy_text(parsed.codex_freshness,"fresh");
    copy_text(parsed.current_time,"--:--");if(!text_field(payload,payload_length,"CT",value,sizeof(value))){if(text_field(payload,payload_length,"UT",value,sizeof(value)))timestamp_clock(parsed.current_time,value);}else timestamp_clock(parsed.current_time,value);parsed.updated_age_seconds=-1;integer_field(payload,payload_length,"UA",&parsed.updated_age_seconds);format_updated(parsed.updated_label,parsed.updated_age_seconds);
    parsed.cpu=parsed.ram=parsed.gpu=-1;percent_field(payload,payload_length,"CPU",&parsed.cpu);percent_field(payload,payload_length,"RP",&parsed.ram);percent_field(payload,payload_length,"GU",&parsed.gpu);if(!text_field(payload,payload_length,"GMU",parsed.gpu_memory_used,sizeof(parsed.gpu_memory_used)))copy_text(parsed.gpu_memory_used,"--");if(!text_field(payload,payload_length,"GMT",parsed.gpu_memory_total,sizeof(parsed.gpu_memory_total)))copy_text(parsed.gpu_memory_total,"--");
    parsed.matrix_completed=parsed.matrix_total=parsed.current_cell=-1;copy_text(parsed.job_name,"--");copy_text(parsed.job_method,"--");integer_field(payload,payload_length,"MC",&parsed.matrix_completed);integer_field(payload,payload_length,"MT",&parsed.matrix_total);integer_field(payload,payload_length,"CI",&parsed.current_cell);text_field(payload,payload_length,"JN",parsed.job_name,sizeof(parsed.job_name));text_field(payload,payload_length,"JM",parsed.job_method,sizeof(parsed.job_method));
    count=0;if(integer_field(payload,payload_length,"EC",&count)&&count>=0&&count<=2)parsed.experiment_count=count;else parsed.experiment_count=0;
    for(i=0;i<2;i++){struct experiment_state *e=&parsed.experiment[i];char key[16];copy_text(e->name,"--");copy_text(e->user,"--");copy_text(e->status,"UNKNOWN");copy_text(e->dataset,"--");copy_text(e->metric_name,"--");copy_text(e->metric_value,"--");copy_text(e->job_name,parsed.job_name);copy_text(e->job_method,parsed.job_method);e->matrix_completed=parsed.matrix_completed;e->matrix_total=parsed.matrix_total;e->current_cell=parsed.current_cell;e->progress=e->current_round=e->total_round=e->elapsed_seconds=e->seed=-1;if(i>=parsed.experiment_count)continue;
        experiment_key(key,i,"N");text_field(payload,payload_length,key,e->name,sizeof(e->name));experiment_key(key,i,"U");text_field(payload,payload_length,key,e->user,sizeof(e->user));experiment_key(key,i,"S");text_field(payload,payload_length,key,e->status,sizeof(e->status));experiment_key(key,i,"P");integer_field(payload,payload_length,key,&e->progress);experiment_key(key,i,"R");integer_field(payload,payload_length,key,&e->current_round);experiment_key(key,i,"T");integer_field(payload,payload_length,key,&e->total_round);experiment_key(key,i,"E");integer_field(payload,payload_length,key,&e->elapsed_seconds);experiment_key(key,i,"D");text_field(payload,payload_length,key,e->dataset,sizeof(e->dataset));experiment_key(key,i,"SD");integer_field(payload,payload_length,key,&e->seed);experiment_key(key,i,"MN");text_field(payload,payload_length,key,e->metric_name,sizeof(e->metric_name));experiment_key(key,i,"MV");text_field(payload,payload_length,key,e->metric_value,sizeof(e->metric_value));
    }
    parsed.five_hour=parsed.week=parsed.reset_cards=-1;copy_text(parsed.five_hour_reset,"--");copy_text(parsed.week_reset,"--");integer_field(payload,payload_length,"C5",&parsed.five_hour);integer_field(payload,payload_length,"CW",&parsed.week);integer_field(payload,payload_length,"CRC",&parsed.reset_cards);text_field(payload,payload_length,"C5R",parsed.five_hour_reset,sizeof(parsed.five_hour_reset));text_field(payload,payload_length,"CWR",parsed.week_reset,sizeof(parsed.week_reset));*state=parsed;last_parse_reason="ok";return 1;
}

static void format_elapsed(char *out,int seconds){char number[16];int hours,minutes;if(seconds<0){copy_text(out,"--");return;}hours=seconds/3600;minutes=(seconds%3600)/60;number_text(number,hours);copy_text(out,number);append_text(out,":",16);if(minutes<10)append_text(out,"0",16);number_text(number,minutes);append_text(out,number,16);}
static void format_elapsed_matrix(char *out,int seconds){char number[16];int hours,minutes;if(seconds<0){copy_text(out,"--");return;}hours=seconds/3600;minutes=(seconds%3600)/60;number_text(number,hours);copy_text(out,number);append_text(out,"H",16);if(minutes<10)append_text(out,"0",16);number_text(number,minutes);append_text(out,number,16);append_text(out,"M",16);}
static void format_round(char *out,int current,int total){char number[16];if(current<0||total<0){copy_text(out,"--/--");return;}number_text(out,current);append_text(out,"/",16);number_text(number,total);append_text(out,number,16);}
static void timestamp_clock(char *out,const char *timestamp){int offset=0;if(timestamp[2]!=':'){while(timestamp[offset]&&timestamp[offset]!='T'&&timestamp[offset]!=' ')offset++;if(!timestamp[offset]){copy_text(out,"--:--");return;}offset++;}if(timestamp[offset]>='0'&&timestamp[offset]<='9'&&timestamp[offset+1]>='0'&&timestamp[offset+1]<='9'&&timestamp[offset+2]==':'&&timestamp[offset+3]>='0'&&timestamp[offset+3]<='9'&&timestamp[offset+4]>='0'&&timestamp[offset+4]<='9'){out[0]=timestamp[offset];out[1]=timestamp[offset+1];out[2]=':';out[3]=timestamp[offset+3];out[4]=timestamp[offset+4];out[5]='\0';}else copy_text(out,"--:--");}
static void format_updated(char *out,int seconds){char number[16];copy_text(out,"UPDATED ");if(seconds<0){append_text(out,"--",24);return;}if(seconds<=2){append_text(out,"NOW",24);return;}if(seconds<60){number_text(number,seconds);append_text(out,number,24);append_text(out,"S AGO",24);}else if(seconds<3600){number_text(number,seconds/60);append_text(out,number,24);append_text(out,"M AGO",24);}else{number_text(number,seconds/3600);append_text(out,number,24);append_text(out,"H AGO",24);}}
static int parse_gpu_value(const char *in,int *whole,int *tenths,int *has_fraction){int i=0;*whole=0;*tenths=0;*has_fraction=0;if(!in||!*in)return 0;while(in[i]>='0'&&in[i]<='9'){*whole=*whole*10+in[i]-'0';if(*whole>1000000)return 0;i++;}if(in[i]=='.'){*has_fraction=1;i++;if(in[i]>='0'&&in[i]<='9')*tenths=in[i]-'0';else return 0;i++;while(in[i]>='0'&&in[i]<='9')i++;}return i>0&&in[i]=='\0';}
static void format_gpu_value(char *out,const char *in,int total){int whole,tenths,has_fraction;char fraction[2];if(!parse_gpu_value(in,&whole,&tenths,&has_fraction)){copy_text(out,"--");return;}if(total&&has_fraction&&tenths>=9)whole++;number_text(out,whole);if(!total&&has_fraction){fraction[0]=(char)('0'+tenths);fraction[1]='\0';append_text(out,".",16);append_text(out,fraction,16);}}
static uint32_t status_color(const char *status,uint32_t green,uint32_t yellow,uint32_t red){if(same_text(status,"ERROR"))return red;if(same_text(status,"COMPLETED")||same_text(status,"RUNNING"))return green;return yellow;}
static const char *server_badge(const struct local_state *state){if(same_text(state->server_freshness,"stale"))return "STALE";if(same_text(state->server_freshness,"offline")||same_text(state->server_status,"offline"))return "OFFLINE";if(same_text(state->server_freshness,"error"))return "ERROR";if(same_text(state->server_status,"degraded"))return "DEGRADED";return same_text(state->server_status,"online")?"ONLINE":"UNKNOWN";}
static void draw_progress_bar(struct framebuffer *fb,int x,int y,int width,int value,uint32_t fill,uint32_t border){int bounded=value,filled;uint32_t track=pack_rgb(&fb->var,RB_COLOR_TRACK_R,RB_COLOR_TRACK_G,RB_COLOR_TRACK_B);if(bounded>100)bounded=100;if(bounded<0)bounded=0;line_rect(fb,x,y,width,RB_PROGRESS_BAR_H,border);rect(fb,x+1,y+1,width-2,RB_PROGRESS_BAR_H-2,track);if(value<0)return;filled=(width-4)*bounded/100;if(filled>0)rect(fb,x+2,y+2,filled,RB_PROGRESS_FILL_H,fill);}

static void draw_header(struct framebuffer *fb,const struct local_state *state,uint32_t text,uint32_t muted,uint32_t green,uint32_t yellow,uint32_t red){char line[96],number[16],used[16],total[16];const char *badge=server_badge(state);int cached=same_text(badge,"ONLINE")||same_text(badge,"STALE")||same_text(badge,"DEGRADED");uint32_t color=same_text(badge,"ONLINE")?green:(same_text(badge,"STALE")||same_text(badge,"DEGRADED")?yellow:red);rect(fb,0,0,RUNBOARD_SCREEN_W,RUNBOARD_SCREEN_H,pack_rgb(&fb->var,RB_COLOR_BG_R,RB_COLOR_BG_G,RB_COLOR_BG_B));draw_text_scaled3(fb,12,3,&font_header,"RUNBOARD",text);draw_fit(fb,RB_CURRENT_TIME_X,RB_CURRENT_TIME_Y,&font_label,state->current_time,1,muted,RB_CURRENT_TIME_W);draw_fit(fb,RB_STATUS_X,RB_STATUS_Y,&font_label,badge,1,color,RB_STATUS_W);if(state->matrix_total>0||state->experiment_count>=2||state->experiment_count==0||state->experiment_count==1||same_text(badge,"OFFLINE")){draw_fit(fb,RB_SERVER_X,RB_SERVER_Y,&font_label,state->server,0,muted,RB_SERVER_W);copy_text(line,"CPU ");if(state->cpu<0||!cached)append_text(line,"--",sizeof(line));else{number_text(number,state->cpu);append_text(line,number,sizeof(line));}append_text(line,"% RAM ",sizeof(line));if(state->ram<0||!cached)append_text(line,"--",sizeof(line));else{number_text(number,state->ram);append_text(line,number,sizeof(line));}append_text(line,"% GPU ",sizeof(line));if(state->gpu<0||!cached)append_text(line,"--",sizeof(line));else{number_text(number,state->gpu);append_text(line,number,sizeof(line));}if(cached){format_gpu_value(used,state->gpu_memory_used,0);format_gpu_value(total,state->gpu_memory_total,1);append_text(line,"% ",sizeof(line));append_text(line,used,sizeof(line));append_text(line,"/",sizeof(line));append_text(line,total,sizeof(line));}else if(same_text(badge,"OFFLINE"))append_text(line,"% --/--G",sizeof(line));else append_text(line,"% --/--",sizeof(line));draw_fit(fb,RB_RESOURCE_X,RB_RESOURCE_Y,&font_label,line,1,muted,RB_RESOURCE_W);}else{draw_fit(fb,12,25,&font_label,state->server,0,muted,155);copy_text(line,"CPU ");if(state->cpu<0||!cached)append_text(line,"--",sizeof(line));else{number_text(number,state->cpu);append_text(line,number,sizeof(line));}append_text(line,"%  RAM ",sizeof(line));if(state->ram<0||!cached)append_text(line,"--",sizeof(line));else{number_text(number,state->ram);append_text(line,number,sizeof(line));}append_text(line,"%  GPU ",sizeof(line));if(state->gpu<0||!cached)append_text(line,"--",sizeof(line));else{number_text(number,state->gpu);append_text(line,number,sizeof(line));}append_text(line,"%",sizeof(line));draw_fit(fb,180,25,&font_label,line,1,muted,288);if(state->matrix_total>0){copy_text(line,"VRAM ");if(same_text(badge,"ONLINE")){append_text(line,state->gpu_memory_used,sizeof(line));append_text(line,"/",sizeof(line));append_text(line,state->gpu_memory_total,sizeof(line));}else append_text(line,"--/--",sizeof(line));draw_fit(fb,180,37,&font_label,line,0,muted,150);}}}

static void draw_experiment(struct framebuffer *fb,const struct experiment_state *e,const char *gpu_memory_used,const char *gpu_memory_total,int x,int y,int width,int height,int detailed,uint32_t text,uint32_t muted,uint32_t green,uint32_t yellow,uint32_t red,uint32_t border){char line[96],value[32];int progress=e->progress;uint32_t fill=status_color(e->status,green,yellow,red);if(progress<0)progress=0;if(progress>100)progress=100;line_rect(fb,x,y,width,height,border);draw_text(fb,x+10,y+7,&font_label,"CURRENT EXPERIMENT",1,muted);draw_fit(fb,x+10,y+22,&font_label,e->name,0,text,300);draw_fit(fb,x+344,y+22,&font_label,e->status,0,fill,width-354);copy_text(line,"USER ");append_text(line,e->user,sizeof(line));draw_fit(fb,x+10,y+39,&font_label,line,0,muted,width-20);copy_text(line,"PROGRESS ");if(e->progress<0)append_text(line,"--",sizeof(line));else{number_text(value,e->progress);append_text(line,value,sizeof(line));append_text(line,"%",sizeof(line));}draw_fit(fb,x+10,y+54,&font_label,line,0,text,width-20);if(detailed){line_rect(fb,x+10,y+68,width-20,7,border);if(e->progress>=0)rect(fb,x+12,y+70,(width-24)*progress/100,3,fill);}else draw_progress_bar(fb,x+10,y+68,width-20,e->progress,fill,border);copy_text(line,"ROUND ");format_round(value,e->current_round,e->total_round);append_text(line,value,sizeof(line));draw_fit(fb,x+10,y+84,&font_label,line,0,muted,200);copy_text(line,"TIME ");format_elapsed(value,e->elapsed_seconds);append_text(line,value,sizeof(line));draw_fit(fb,x+242,y+84,&font_label,line,0,muted,width-252);copy_text(line,"DATA ");append_text(line,e->dataset,sizeof(line));draw_fit(fb,x+10,y+100,&font_label,line,0,muted,200);copy_text(line,"SEED ");if(e->seed<0)append_text(line,"--",sizeof(line));else{number_text(value,e->seed);append_text(line,value,sizeof(line));}draw_fit(fb,x+242,y+100,&font_label,line,0,muted,width-252);if(detailed){copy_text(line,"METRIC ");append_text(line,e->metric_name,sizeof(line));append_text(line," ",sizeof(line));append_text(line,e->metric_value,sizeof(line));draw_fit(fb,x+10,y+116,&font_label,line,0,text,200);copy_text(line,"VRAM ");append_text(line,gpu_memory_used,sizeof(line));append_text(line,"/",sizeof(line));append_text(line,gpu_memory_total,sizeof(line));draw_fit(fb,x+242,y+116,&font_label,line,0,text,width-252);}}

static void draw_footer(struct framebuffer *fb,const struct local_state *state,uint32_t text,uint32_t muted,uint32_t panel){char line[96],value[32];uint32_t bg=pack_rgb(&fb->var,RB_COLOR_BG_R,RB_COLOR_BG_G,RB_COLOR_BG_B);int offline=same_text(server_badge(state),"OFFLINE");rect(fb,0,RUNBOARD_FOOTER_Y,RUNBOARD_SCREEN_W,RUNBOARD_SCREEN_H-RUNBOARD_FOOTER_Y,panel);if(state->experiment_count>=2){rect(fb,RB_SECOND_CARD_X,RB_SECOND_CARD_Y,RB_SECOND_CARD_W,RB_SECOND_CARD_H,bg);line_rect(fb,RB_SECOND_CARD_X,RB_SECOND_CARD_Y,RB_SECOND_CARD_W,RB_SECOND_CARD_H,muted);draw_text(fb,22,RB_SECOND_TITLE_Y,&font_label,"SECOND EXPERIMENT",1,muted);draw_fit(fb,22,RB_SECOND_DETAIL_Y,&font_label,state->experiment[1].name,0,text,326);draw_fit(fb,360,RB_SECOND_DETAIL_Y,&font_label,state->experiment[1].status,0,text,98);draw_fit(fb,22,RB_SECOND_VALUE_Y,&font_label,state->experiment[1].user,0,muted,100);copy_text(line,"PROGRESS ");if(state->experiment[1].progress<0)append_text(line,"--",sizeof(line));else{number_text(value,state->experiment[1].progress);append_text(line,value,sizeof(line));append_text(line,"%",sizeof(line));}draw_fit(fb,138,RB_SECOND_VALUE_Y,&font_label,line,0,muted,110);copy_text(line,"ROUND ");format_round(value,state->experiment[1].current_round,state->experiment[1].total_round);append_text(line,value,sizeof(line));draw_fit(fb,260,RB_SECOND_VALUE_Y,&font_label,line,0,muted,198);}if(!offline&&(!same_text(state->server_freshness,"fresh")||!same_text(state->codex_freshness,"fresh"))){if(!same_text(state->server_freshness,"fresh")){copy_text(line,"SERVER ");append_text(line,state->server_freshness,sizeof(line));}else{copy_text(line,"CODEX ");append_text(line,state->codex_freshness,sizeof(line));}draw_fit(fb,334,RUNBOARD_FOOTER_Y+9,&font_label,line,0,text,136);}}

static uint32_t quota_color(int percent,uint32_t normal,uint32_t yellow,uint32_t red,uint32_t muted){if(percent<0)return muted;if(percent<20)return red;if(percent<50)return yellow;return normal;}
static void draw_quota_row(struct framebuffer *fb,int y,int percent,const char *reset,uint32_t normal,uint32_t yellow,uint32_t red,uint32_t muted,uint32_t border){char line[32],number[16];uint32_t color=quota_color(percent,normal,yellow,red,muted);if(percent<0)copy_text(line,"--%");else{number_text(number,percent);copy_text(line,number);append_text(line,"%",sizeof(line));}draw_fit(fb,RB_CODEX_PERCENT_X,y,&font_label,line,0,color,30);draw_progress_bar(fb,RB_CODEX_BAR_X,y+2,RB_CODEX_BAR_W,percent,color,border);draw_fit(fb,RB_CODEX_RESET_X,y,&font_label,reset,0,muted,RB_CODEX_RESET_W);}
static void draw_matrix_footer(struct framebuffer *fb,const struct local_state *state,uint32_t text,uint32_t muted,uint32_t panel){uint32_t normal_five=pack_rgb(&fb->var,RB_COLOR_GREEN_R,RB_COLOR_GREEN_G,RB_COLOR_GREEN_B),normal_week=pack_rgb(&fb->var,RB_COLOR_BLUE_R,RB_COLOR_BLUE_G,RB_COLOR_BLUE_B),yellow=pack_rgb(&fb->var,RB_COLOR_YELLOW_R,RB_COLOR_YELLOW_G,RB_COLOR_YELLOW_B),red=pack_rgb(&fb->var,RB_COLOR_RED_R,RB_COLOR_RED_G,RB_COLOR_RED_B),border=pack_rgb(&fb->var,RB_COLOR_BORDER_R,RB_COLOR_BORDER_G,RB_COLOR_BORDER_B);(void)text;rect(fb,0,RUNBOARD_FOOTER_Y,RUNBOARD_SCREEN_W,RUNBOARD_SCREEN_H-RUNBOARD_FOOTER_Y,panel);draw_quota_row(fb,RB_CODEX_ROW1_Y,state->five_hour,state->five_hour_reset,normal_five,yellow,red,muted,border);draw_quota_row(fb,RB_CODEX_ROW2_Y,state->week,state->week_reset,normal_week,yellow,red,muted,border);}
static void draw_footer_right(struct framebuffer *fb,const struct local_state *state,uint32_t text,uint32_t muted,uint32_t panel){char line[32];int offline=same_text(server_badge(state),"OFFLINE");if(state->experiment_count<2)draw_matrix_footer(fb,state,text,muted,panel);rect(fb,RB_UPDATED_STATUS_X,RUNBOARD_FOOTER_Y,RB_UPDATED_W,RUNBOARD_SCREEN_H-RUNBOARD_FOOTER_Y,panel);if(!offline&&(!same_text(state->server_freshness,"fresh")||!same_text(state->codex_freshness,"fresh"))){if(!same_text(state->server_freshness,"fresh")){copy_text(line,"SERVER ");append_text(line,state->server_freshness,sizeof(line));}else{copy_text(line,"CODEX ");append_text(line,state->codex_freshness,sizeof(line));}draw_fit(fb,RB_UPDATED_STATUS_X,RB_UPDATED_STATUS_Y,&font_label,line,0,text,RB_UPDATED_W);}if(state->experiment_count<2)draw_fit(fb,RB_UPDATED_X,RB_UPDATED_Y,&font_label,state->updated_label,0,muted,RB_UPDATED_W);}

static void draw_screen(struct framebuffer *fb,const struct local_state *state){uint32_t text=pack_rgb(&fb->var,RB_COLOR_TEXT_R,RB_COLOR_TEXT_G,RB_COLOR_TEXT_B),muted=pack_rgb(&fb->var,RB_COLOR_MUTED_R,RB_COLOR_MUTED_G,RB_COLOR_MUTED_B),green=pack_rgb(&fb->var,RB_COLOR_GREEN_R,RB_COLOR_GREEN_G,RB_COLOR_GREEN_B),yellow=pack_rgb(&fb->var,RB_COLOR_YELLOW_R,RB_COLOR_YELLOW_G,RB_COLOR_YELLOW_B),red=pack_rgb(&fb->var,RB_COLOR_RED_R,RB_COLOR_RED_G,RB_COLOR_RED_B),border=pack_rgb(&fb->var,RB_COLOR_BORDER_R,RB_COLOR_BORDER_G,RB_COLOR_BORDER_B),panel=pack_rgb(&fb->var,RB_COLOR_PANEL_R,RB_COLOR_PANEL_G,RB_COLOR_PANEL_B);const char *badge;draw_header(fb,state,text,muted,green,yellow,red);badge=server_badge(state);if(same_text(badge,"OFFLINE")){uint32_t bg=pack_rgb(&fb->var,RB_COLOR_BG_R,RB_COLOR_BG_G,RB_COLOR_BG_B);line_rect(fb,12,58,456,158,border);rect(fb,13,59,454,156,bg);draw_fit(fb,172,96,&font_label,"SERVER OFFLINE",1,text,136);draw_fit(fb,150,126,&font_label,"NO LIVE SERVER DATA",1,muted,180);}else if(!state->valid||same_text(badge,"ERROR")){line_rect(fb,12,58,456,158,border);draw_text(fb,184,112,&font_large_number,badge,2,red);}else if(state->experiment_count==0){line_rect(fb,12,58,456,158,border);draw_text(fb,184,94,&font_large_number,"IDLE",2,green);draw_text(fb,165,132,&font_label,"NO ACTIVE EXPERIMENT",1,muted);}else if(state->experiment_count==1&&state->matrix_total>0){draw_matrix_experiment(fb,&state->experiment[0],state->gpu_memory_used,state->gpu_memory_total,text,muted,green,yellow,red,border);}else{draw_experiment(fb,&state->experiment[0],state->gpu_memory_used,state->gpu_memory_total,12,48,456,130,0,text,muted,green,yellow,red,border);}draw_footer(fb,state,text,muted,panel);draw_footer_right(fb,state,text,muted,panel);}

static int serial_open(const char *path,struct termios *saved){struct termios t;int fd=open(path,O_RDWR|O_NOCTTY|O_NONBLOCK);if(fd<0)return -1;if(ioctl(fd,TCGETS,&t)<0){close(fd);return -1;}*saved=t;t.c_iflag&=~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL|IXON|IXOFF|IXANY);t.c_oflag&=~OPOST;t.c_lflag&=~(ECHO|ECHONL|ICANON|ISIG|IEXTEN);t.c_cflag&=~(CSIZE|PARENB|PARODD|CSTOPB);
#ifdef CRTSCTS
    t.c_cflag&=~CRTSCTS;
#endif
    t.c_cflag|=CS8|CLOCAL|CREAD;t.c_ispeed=B115200;t.c_ospeed=B115200;t.c_cc[VMIN]=0;t.c_cc[VTIME]=0;if(ioctl(fd,TCSETS,&t)<0){close(fd);return -1;}return fd;}
static void serial_close(int fd,const struct termios *saved){if(fd>=0){ioctl(fd,TCSETS,saved);close(fd);}}
static void serial_debug(int fd,const struct local_state *state,int frame_length,int parsed,const char *phase){char line[512],number[16];int written;line[0]='\0';append_text(line,"RBDBG|phase=",sizeof(line));append_text(line,phase,sizeof(line));append_text(line,"|bytes=",sizeof(line));number_text(number,frame_length);append_text(line,number,sizeof(line));append_text(line,"|last=",sizeof(line));append_text(line,state->valid?"1":"0",sizeof(line));append_text(line,"|len=",sizeof(line));append_text(line,last_length_ok?"OK":"FAIL",sizeof(line));append_text(line,"|crc=",sizeof(line));append_text(line,last_crc_ok?"OK":"FAIL",sizeof(line));append_text(line,"|parse=",sizeof(line));append_text(line,parsed?"OK":"FAIL",sizeof(line));append_text(line,"|reason=",sizeof(line));append_text(line,last_parse_reason,sizeof(line));append_text(line,"|ss=",sizeof(line));append_text(line,state->server_status,sizeof(line));append_text(line,"|sf=",sizeof(line));append_text(line,state->server_freshness,sizeof(line));append_text(line,"|cf=",sizeof(line));append_text(line,state->codex_freshness,sizeof(line));append_text(line,"|ec=",sizeof(line));number_text(number,state->experiment_count);append_text(line,number,sizeof(line));append_text(line,"|cpu=",sizeof(line));number_text(number,state->cpu);append_text(line,number,sizeof(line));append_text(line,"|ram=",sizeof(line));number_text(number,state->ram);append_text(line,number,sizeof(line));append_text(line,"|gpu=",sizeof(line));number_text(number,state->gpu);append_text(line,number,sizeof(line));append_text(line,"|seq=",sizeof(line));number_text(number,(int)state->sequence);append_text(line,number,sizeof(line));append_text(line,"|mc=",sizeof(line));number_text(number,state->matrix_completed);append_text(line,number,sizeof(line));append_text(line,"|mt=",sizeof(line));number_text(number,state->matrix_total);append_text(line,number,sizeof(line));append_text(line,"|ci=",sizeof(line));number_text(number,state->current_cell);append_text(line,number,sizeof(line));append_text(line,"|jn=",sizeof(line));append_text(line,state->job_name,sizeof(line));append_text(line,"|jm=",sizeof(line));append_text(line,state->job_method,sizeof(line));append_text(line,"|c5=",sizeof(line));number_text(number,state->five_hour);append_text(line,number,sizeof(line));append_text(line,"|cw=",sizeof(line));number_text(number,state->week);append_text(line,number,sizeof(line));append_text(line,"|exp0=",sizeof(line));append_text(line,state->experiment[0].name,sizeof(line));append_text(line,"\n",sizeof(line));written=(int)write(fd,line,(size_t)text_length(line));if(written<0)return;}
static int is_quit(const char *frame){return same_text(frame,"<RBQUIT>");}

int main(int argc,char **argv){struct framebuffer fb;struct local_state state;struct termios saved_serial;char frame[RB_FRAME_MAX+1];int fd=-1,n=0,overflow=0,i;const char *serial_path="/dev/s3c2410_serial0";fb.fd=-1;fb.memory=MAP_FAILED;fb.mapped_length=0;memset(&fb.var,0,sizeof(fb.var));memset(&fb.fix,0,sizeof(fb.fix));memset(&state,0,sizeof(state));memset(&saved_serial,0,sizeof(saved_serial));state.cpu=state.ram=state.gpu=state.five_hour=state.week=state.reset_cards=-1;state.updated_age_seconds=-1;copy_text(state.current_time,"--:--");format_updated(state.updated_label,state.updated_age_seconds);copy_text(state.server,"SERVER-01");copy_text(state.server_status,"offline");copy_text(state.server_freshness,"offline");copy_text(state.codex_freshness,"unknown");copy_text(state.gpu_memory_used,"--");copy_text(state.gpu_memory_total,"--");copy_text(state.five_hour_reset,"--");copy_text(state.week_reset,"--");if(argc==3&&same_text(argv[1],"--serial"))serial_path=argv[2];else if(argc!=1)return 2;if(fb_open(&fb)<0)return 1;fd=serial_open(serial_path,&saved_serial);if(fd<0){fb_close(&fb);return 1;}draw_screen(&fb,&state);for(;;){unsigned char bytes[96];struct timespec pause={1,0};int count=(int)read(fd,bytes,sizeof(bytes));if(count>0)for(i=0;i<count;i++){if(bytes[i]=='\n'){if(!overflow&&n>0){if(frame[n-1]=='\r')n--;frame[n]='\0';if(is_quit(frame)){serial_close(fd,&saved_serial);fb_close(&fb);return 0;}frame[n]='\n';frame[n+1]='\0';if(find_text(frame,"RB1|")==frame){int parsed=parse_rb1(frame,n+1,&state);serial_debug(fd,&state,n+1,parsed,"PARSED");if(parsed){draw_screen(&fb,&state);serial_debug(fd,&state,n+1,parsed,"DRAWN");}}}n=0;overflow=0;}else if(n<RB_FRAME_MAX&&!overflow)frame[n++]=(char)bytes[i];else overflow=1;}nanosleep(&pause,NULL);}}
static void draw_matrix_experiment(struct framebuffer *fb,const struct experiment_state *e,const char *gpu_memory_used,const char *gpu_memory_total,uint32_t text,uint32_t muted,uint32_t green,uint32_t yellow,uint32_t red,uint32_t border){char line[96],value[32];int matrix_progress=-1,round_progress=-1;uint32_t status=status_color(e->status,green,yellow,red),label=pack_rgb(&fb->var,RB_COLOR_LABEL_R,RB_COLOR_LABEL_G,RB_COLOR_LABEL_B);muted=label;(void)gpu_memory_used;(void)gpu_memory_total;if(e->matrix_completed>=0&&e->matrix_total>0)matrix_progress=e->matrix_completed*100/e->matrix_total;if(e->current_round>=0&&e->total_round>0)round_progress=e->current_round*100/e->total_round;line_rect(fb,RB_MATRIX_PANEL_X,RB_MATRIX_PANEL_Y,RB_MATRIX_PANEL_W,RB_MATRIX_PANEL_H,border);draw_text(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_TITLE_Y,&font_label,"CURRENT EXPERIMENT",1,muted);draw_fit(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_JOB_Y,&font_label,e->job_name,0,text,300);draw_fit(fb,RB_MATRIX_PANEL_X+344,RB_MATRIX_JOB_Y,&font_label,e->status,0,status,RB_MATRIX_PANEL_W-354);copy_text(line,"USER ");append_text(line,e->user,sizeof(line));draw_fit(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_USER_Y,&font_label,line,0,muted,420);copy_text(line,"MATRIX ");if(e->matrix_completed<0||e->matrix_total<1)append_text(line,"--/--",sizeof(line));else{number_text(value,e->matrix_completed);append_text(line,value,sizeof(line));append_text(line,"/",sizeof(line));number_text(value,e->matrix_total);append_text(line,value,sizeof(line));}draw_fit(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_COUNT_Y,&font_label,line,0,text,200);copy_text(line,"CELL ");if(e->current_cell<1||e->matrix_total<1)append_text(line,"--/--",sizeof(line));else{number_text(value,e->current_cell);append_text(line,value,sizeof(line));append_text(line,"/",sizeof(line));number_text(value,e->matrix_total);append_text(line,value,sizeof(line));}draw_fit(fb,RB_MATRIX_PANEL_X+242,RB_MATRIX_COUNT_Y,&font_label,line,0,text,RB_MATRIX_PANEL_W-252);draw_progress_bar(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_BAR_Y,RB_MATRIX_PANEL_W-20,matrix_progress,green,border);copy_text(line,"METHOD ");append_text(line,e->job_method,sizeof(line));draw_fit(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_IDENTITY_Y,&font_label,line,0,muted,230);copy_text(line,"DATA ");append_text(line,e->dataset,sizeof(line));append_text(line,"  S",sizeof(line));if(e->seed<0)append_text(line,"--",sizeof(line));else{number_text(value,e->seed);append_text(line,value,sizeof(line));}draw_fit(fb,RB_MATRIX_PANEL_X+242,RB_MATRIX_IDENTITY_Y,&font_label,line,0,muted,RB_MATRIX_PANEL_W-252);copy_text(line,"ROUND ");format_round(value,e->current_round,e->total_round);append_text(line,value,sizeof(line));draw_fit(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_ROUND_Y,&font_label,line,0,text,200);copy_text(line,"TIME ");format_elapsed_matrix(value,e->elapsed_seconds);append_text(line,value,sizeof(line));draw_fit(fb,RB_MATRIX_PANEL_X+242,RB_MATRIX_TIME_Y,&font_label,line,0,muted,RB_MATRIX_PANEL_W-252);draw_progress_bar(fb,RB_MATRIX_PANEL_X+10,RB_MATRIX_ROUND_BAR_Y,RB_MATRIX_PANEL_W-20,round_progress,status,border);}
